import { extend } from 'flarum/common/extend';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import app from 'flarum/forum/app';
import UserWelcomeBox from './components/UserWelcomeBox';
import GuestWelcomeBox from './components/GuestWelcomeBox';
export default function addWelcomeBox() {
  extend(IndexSidebar.prototype, 'items', function (items) {
    if (app.current?.get('routeName') !== 'index') return;
    const user = app.session.user;
    if (user) {
      items.add('welcomeBox', m(UserWelcomeBox, {
        user: user
      }), 20);
    } else {
      items.add('welcomeBoxGuest', m(GuestWelcomeBox, null), 20);
    }
  });
}